from fractions import Fraction

def to_rational(x: float, max_denom: int = 12) -> str:
    val = x % 1.0
    if abs(val - 1.0) < 1e-6:
        val = 0.0

    f = Fraction(val).limit_denominator(max_denom)

    if f.numerator == f.denominator:
        return "0"

    if f.denominator == 1:
        return str(f.numerator)
    else:
        return f"{f.numerator}/{f.denominator}"

if __name__ == "__main__":
    coords = [0.0, 0.5, 0.5, 0.38538014, 0.11461986, 0.88538014]
    for c in coords:
        print(f"{c} -> {to_rational(c)}")

